 12→	"github.com/entireio/cli/cmd/entire/cli/paths"
 13→)
 14→
 15→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 16→// Returns nil if the hook has no lifecycle significance.
 17→func (c *CursorAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 18→	switch hookName {
 19→	case HookNameSessionStart:
 20→		return c.parseSessionStart(stdin)
 21→	case HookNameBeforeSubmitPrompt:
 22→		return c.parseTurnStart(ctx, stdin)
 23→	case HookNameStop:
 24→		return c.parseTurnEnd(ctx, stdin)
 25→	case HookNameSessionEnd:
 26→		return c.parseSessionEnd(ctx, stdin)
 27→	case HookNamePreCompact:
 28→		return c.parsePreCompact(stdin)
 29→	case HookNameSubagentStart:
 30→		return c.parseSubagentStart(stdin)
 31→	case HookNameSubagentStop:
 32→		return c.parseSubagentStop(stdin)
 33→	default:
 34→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 35→	}
 36→}
 37→
 38→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 39→func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 40→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 41→	if err != nil {
 42→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 43→	}
 44→	return data, nil
 45→}
 46→
 47→// Note: CursorAgent does NOT implement TranscriptAnalyzer. Cursor's transcript
 48→// format does not contain tool_use blocks that would allow extracting modified
 49→// files. File detection relies on git status instead.
 50→
 51→// --- Internal hook parsing functions ---
 52→
 53→// resolveTranscriptRef returns the transcript path from the hook input, or computes
 54→// it dynamically when the hook doesn't provide one (Cursor CLI pattern).
 55→func (c *CursorAgent) resolveTranscriptRef(ctx context.Context, conversationID, rawPath string) string {
 56→	if rawPath != "" {
 57→		return rawPath
 58→	}
 59→
 60→	repoRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		logging.Warn(ctx, "cursor: failed to get worktree root for transcript resolution", "err", err)
 63→		return ""
 64→	}
 65→
 66→	sessionDir, err := c.GetSessionDir(repoRoot)
 67→	if err != nil {
 68→		logging.Warn(ctx, "cursor: failed to get session dir for transcript resolution", "err", err)
 69→		return ""
 70→	}
 71→
 72→	return c.ResolveSessionFile(sessionDir, conversationID)
 73→}
 74→
 75→func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
 76→	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
 77→	if err != nil {
 78→		return nil, err
 79→	}
 80→	return &agent.Event{
 81→		Type:       agent.SessionStart,
 82→		SessionID:  raw.ConversationID,
 83→		SessionRef: raw.TranscriptPath,
 84→		Timestamp:  time.Now(),
 85→	}, nil
 86→}
 87→
 88→func (c *CursorAgent) parseTurnStart(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
 89→	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
 90→	if err != nil {
 91→		return nil, err
 92→	}
 93→	return &agent.Event{
 94→		Type:       agent.TurnStart,
 95→		SessionID:  raw.ConversationID,
 96→		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
 97→		Prompt:     raw.Prompt,
 98→		Timestamp:  time.Now(),
 99→	}, nil
100→}
101→
102→func (c *CursorAgent) parseTurnEnd(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
103→	raw, err := agent.ReadAndParseHookInput[stopHookInputRaw](stdin)
104→	if err != nil {
105→		return nil, err
106→	}
107→	return &agent.Event{
108→		Type:       agent.TurnEnd,
109→		SessionID:  raw.ConversationID,
110→		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
111→		Timestamp:  time.Now(),
112→	}, nil
